package com.nequard.security;
import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/security") public class SecurityController{private final SecurityEventRepository repo;public SecurityController(SecurityEventRepository r){repo=r;}@GetMapping("/events")public List<SecurityEvent> events(){return repo.findTop100ByOrderByOccurredAtDesc();}@PostMapping("/events")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','SECURITY_ANALYST')")public SecurityEvent record(@RequestBody SecurityEvent e){return repo.save(e);}}